'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var tryRequire = require( '@stdlib/utils/try-require' );


// FIXTURES //

var UINT32_INTEGER_SEED = require( './fixtures/c/uint32_integer_seed.json' ).expected;
var UINT32_ARRAY_SEED = require( './fixtures/c/uint32_array_seed.json' ).expected;
var FLOAT32_INTEGER_SEED = require( './fixtures/c/float32_integer_seed.json' ).expected;
var FLOAT32_ARRAY_SEED = require( './fixtures/c/float32_array_seed.json' ).expected;


// VARIABLES //

var native = tryRequire( resolve( __dirname, './../lib/native.js' ) );
var opts = {
	'skip': ( native instanceof Error )
};


// TESTS //

tape( 'main export is a function', opts, function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof native, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns expected pseudorandom integers (integer seed)', opts, function test( t ) {
	var expected;
	var actual;
	var i;

	expected = UINT32_INTEGER_SEED;
	actual = native( 1234, expected.length );

	t.strictEqual( actual.length, expected.length, 'returns expected length' );
	for ( i = 0; i < expected.length; i++ ) {
		t.strictEqual( actual[ i ], expected[ i ], 'returns expected value. i: ' + i + '.' );
	}
	t.end();
});

tape( 'the function returns expected pseudorandom integers (array seed)', opts, function test( t ) {
	var expected;
	var actual;
	var seed;
	var i;

	expected = UINT32_ARRAY_SEED;
	seed = [ 291, 564, 837, 1110 ];
	actual = native( seed, expected.length );

	t.strictEqual( actual.length, expected.length, 'returns expected length' );
	for ( i = 0; i < expected.length; i++ ) {
		t.strictEqual( actual[ i ], expected[ i ], 'returns expected value. i: ' + i + '.' );
	}
	t.end();
});

tape( 'the `normalized` method returns expected pseudorandom numbers (integer seed)', opts, function test( t ) {
	var expected;
	var actual;
	var i;

	expected = FLOAT32_INTEGER_SEED;
	actual = native.normalized( 1234, expected.length );

	t.strictEqual( actual.length, expected.length, 'returns expected length' );
	for ( i = 0; i < expected.length; i++ ) {
		t.strictEqual( actual[ i ], expected[ i ], 'returns expected value. i: ' + i + '.' );
	}
	t.end();
});

tape( 'the `normalized` method returns expected pseudorandom numbers (array seed)', opts, function test( t ) {
	var expected;
	var actual;
	var seed;
	var i;

	expected = FLOAT32_ARRAY_SEED;
	seed = [ 291, 564, 837, 1110 ];
	actual = native.normalized( seed, expected.length );

	t.strictEqual( actual.length, expected.length, 'returns expected length' );
	for ( i = 0; i < expected.length; i++ ) {
		t.strictEqual( actual[ i ], expected[ i ], 'returns expected value. i: ' + i + '.' );
	}
	t.end();
});
